  ('N4-01', 'writing', 1, 65, 'picture_sentence', 'Өгөгдсөн үгийг ашиглаж нэг өгүүлбэр бич: 邀请', null, '他邀请我周末去他家吃饭。', 'manual', 1, null, null, false, array['sk.writing.complete','voc.hsk4']::text[], '«邀请 + хүн + үйл» бүтцээр бичнэ. Үг заавал орсон, утга бүтэн өгүүлбэр байхад болно.', null, null, null, null),
  ('N4-01', 'writing', 1, 66, 'picture_sentence', 'Өгөгдсөн үгийг ашиглаж нэг өгүүлбэр бич: 耐心', null, '王老师对学生非常有耐心。', 'manual', 1, null, null, false, array['sk.writing.complete','voc.hsk4']::text[], '«对…有耐心» эсвэл «耐心地 + үйл үг» хэлбэрээр хэрэглэнэ.', null, null, null, null),
  ('N4-01', 'writing', 1, 67, 'picture_sentence', 'Өгөгдсөн үгийг ашиглаж нэг өгүүлбэр бич: 后悔', null, '我很后悔没有早点儿开始学汉语。', 'manual', 1, null, null, false, array['sk.writing.complete','voc.hsk4']::text[], '«后悔 + хийсэн/хийгээгүй зүйл». Харамсаж буй зүйлээ ард нь бичнэ.', null, null, null, null),
  ('N4-01', 'writing', 1, 68, 'picture_sentence', 'Өгөгдсөн үгийг ашиглаж нэг өгүүлбэр бич: 顺利', null, '祝你这次考试一切顺利！', 'manual', 1, null, null, false, array['sk.writing.complete','voc.hsk4']::text[], '«一切顺利», «顺利地 + үйл үг», «…很顺利» зэргээр хэрэглэж болно.', null, null, null, null),
  ('N4-01', 'writing', 1, 69, 'picture_sentence', 'Өгөгдсөн үгийг ашиглаж нэг өгүүлбэр бич: 礼貌', null, '进别人的房间以前先敲门是一种礼貌。', 'manual', 1, null, null, false, array['sk.writing.complete','voc.hsk4']::text[], '«有礼貌 / 不礼貌 / 是一种礼貌». Нэр үг, тэмдэг нэр хоёулаа болно.', null, null, null, null),
  ('N4-01', 'writing', 2, 70, 'essay', '请写一篇不少于 80 字的短文，介绍一下你的一个好朋友。
(80-аас доошгүй ханзтай богино эх бич.)', null, '我最好的朋友叫小明，我们是在中学认识的。他个子很高，性格活泼，特别喜欢打篮球。他学习很认真，也很愿意帮助别人。我遇到不开心的事情时，他总是耐心地听我说，然后想办法让我高兴起来。虽然现在我们不在一个城市，但是我们经常在网上聊天儿。我希望我们永远是好朋友。', 'manual', 1, null, null, false, array['sk.writing.essay']::text[], 'Бүтэц: хэн бэ, хаана танилцсан → гадаад төрх, зан чанар → нэг жишээ → одоо ямар харилцаатай, хүсэл. 80-аас доошгүй ханз, цэг таслалаа зөв тавь.', null, null, null, null)
